  priceChangePercent: ((newPrice - (marketData.currentPrice || item.basePrice)) / (marketData.currentPrice || item.basePrice)) * 100,
  supplyDemandRatio: supplyDemandRatio,
  priceTrend: priceTrend,
  volatility: volatility,
  manipulationScore: manipulationScore,
  timestamp: new Date().toISOString()
};

