async function fetchMarketData(itemId, regionId) {
  // Mock market data - in production this would query the database
  return {
    currentPrice: Math.floor(Math.random() * 1000) + 100,
    totalSupply: Math.floor(Math.random() * 1000),
    totalDemand: Math.floor(Math.random() * 1000),
    recentSales: Math.floor(Math.random() * 50),
    averagePrice: Math.floor(Math.random() * 1000) + 100,
    priceHistory: Array.from({ length: 24 }, () => Math.floor(Math.random() * 1000) + 100)
  };
}

function calculateSupplyDemandRatio(marketData) {
  if (marketData.totalDemand === 0) return 10; // Very high demand
  return marketData.totalSupply / marketData.totalDemand;
}

function calculateDynamicPrice(item, marketData, supplyDemandRatio) {
  const basePrice = item.basePrice;
  const elasticity = 0.5; // Price elasticity coefficient

  // Apply supply/demand modifier
  const supplyDemandModifier = 1 / Math.pow(supplyDemandRatio, elasticity);

  // Apply trend modifier
  const trendModifier = 1 + (marketData.recentSales > 20 ? 0.1 : marketData.recentSales < 5 ? -0.05 : 0);

  // Calculate final price
  let finalPrice = basePrice * supplyDemandModifier * trendModifier;

  // Apply bounds (prevent extreme price changes)
  const maxChange = 0.5; // Max 50% change per update
  const minPrice = basePrice * 0.1;
  const maxPrice = basePrice * 10;

  finalPrice = Math.max(minPrice, Math.min(maxPrice, finalPrice));
  finalPrice = Math.max(basePrice * (1 - maxChange), Math.min(basePrice * (1 + maxChange), finalPrice));

  return Math.round(finalPrice * 100) / 100; // Round to 2 decimal places
}

function calculatePriceTrend(itemId, regionId) {
  // Simple trend calculation based on recent price history
  return (Math.random() - 0.5) * 0.2; // Random between -10% and +10%
}

function calculateVolatility(marketData) {
  if (!marketData.priceHistory || marketData.priceHistory.length < 2) return 0.05;

  const prices = marketData.priceHistory;
  const mean = prices.reduce((sum, price) => sum + price, 0) / prices.length;
  const variance = prices.reduce((sum, price) => sum + Math.pow(price - mean, 2), 0) / prices.length;
  const standardDeviation = Math.sqrt(variance);

  return standardDeviation / mean;
}

function detectMarketManipulation(marketData) {
  let score = 0;

  // Check for unusual volume spikes
  if (marketData.recentSales > 100) score += 0.3;

  // Check for price anomalies
  const priceVariance = calculateVolatility(marketData);
  if (priceVariance > 0.3) score += 0.4;

  // Check for supply/demand imbalances
  const ratio = calculateSupplyDemandRatio(marketData);
  if (ratio > 5 || ratio < 0.2) score += 0.3;

  return Math.min(score, 1.0);
}

// Collect all price updates and generate market summary
const allUpdates = $input.all().map(item => item.json);

// Calculate market statistics
const summary = {
  totalUpdates: allUpdates.length,
  averagePriceChange: allUpdates.reduce((sum, update) => sum + update.priceChangePercent, 0) / allUpdates.length,
  priceIncreases: allUpdates.filter(update => update.priceChangePercent > 0).length,
  priceDecreases: allUpdates.filter(update => update.priceChangePercent < 0).length,
  significantChanges: allUpdates.filter(update => Math.abs(update.priceChangePercent) > 10).length,
  highVolatilityItems: allUpdates.filter(update => update.volatility > 0.2).length,
  manipulationFlags: allUpdates.filter(update => update.manipulationScore > 0.7).length,
  timestamp: new Date().toISOString(),
  regions: [...new Set(allUpdates.map(update => update.regionId))],
  categories: [...new Set(allUpdates.map(update => update.categoryId))]
};

// Identify top movers
const topMovers = allUpdates
  .sort((a, b) => Math.abs(b.priceChangePercent) - Math.abs(a.priceChangePercent))
  .slice(0, 10);

// Identify most volatile items
const mostVolatile = allUpdates
  .sort((a, b) => b.volatility - a.volatility)
  .slice(0, 5);

// Regional breakdown
const regionalBreakdown = {};
summary.regions.forEach(region => {
  const regionUpdates = allUpdates.filter(update => update.regionId === region);
  regionalBreakdown[region] = {
    updateCount: regionUpdates.length,
    averageChange: regionUpdates.reduce((sum, update) => sum + update.priceChangePercent, 0) / regionUpdates.length,
    volatility: regionUpdates.reduce((sum, update) => sum + update.volatility, 0) / regionUpdates.length
  };
});

const marketSummary = {
  summary: summary,
  topMovers: topMovers,
  mostVolatile: mostVolatile,
  regionalBreakdown: regionalBreakdown,
  alerts: generateMarketAlerts(summary, topMovers, mostVolatile)
};

return [{ json: marketSummary }];

function generateMarketAlerts(summary, topMovers, mostVolatile) {
  const alerts = [];

  // High volatility alert
  if (summary.highVolatilityItems > summary.totalUpdates * 0.3) {
    alerts.push({
      type: 'high_volatility',
      severity: 'warning',
      message: `High market volatility detected: ${summary.highVolatilityItems} items showing volatile behavior`,
      affectedItems: mostVolatile.length
    });
  }

  // Significant price movement alert
  if (summary.significantChanges > summary.totalUpdates * 0.2) {
    alerts.push({
      type: 'significant_price_movement',
      severity: 'info',
      message: `Significant price movements: ${summary.significantChanges} items changed by more than 10%`,
      topMovers: topMovers.slice(0, 3)
    });
  }

  // Manipulation alert
  if (summary.manipulationFlags > 0) {
    alerts.push({
      type: 'potential_manipulation',
      severity: 'critical',
      message: `Potential market manipulation detected in ${summary.manipulationFlags} items`,
      requiresInvestigation: true
    });
  }

  return alerts;
}

// Check for price alerts triggered by updates
const marketSummary = $input.first().json;
const alerts = [];

// Get active price alerts from database
const priceAlerts = await fetchActivePriceAlerts();

for (const alert of priceAlerts) {
  const relevantUpdate = marketSummary.topMovers.find(mover => 
    mover.itemId === alert.itemId && mover.regionId === alert.regionId
  );

  if (relevantUpdate) {
    let triggered = false;

    switch (alert.type) {
      case 'above':
        triggered = relevantUpdate.newPrice >= alert.threshold;
        break;
      case 'below':
        triggered = relevantUpdate.newPrice <= alert.threshold;
        break;
      case 'percentage_change':
        triggered = Math.abs(relevantUpdate.priceChangePercent) >= alert.threshold;
        break;
    }

    if (triggered) {
      alerts.push({
        alertId: alert.id,
        playerId: alert.playerId,
        itemId: alert.itemId,
        triggerPrice: relevantUpdate.newPrice,
        triggerData: relevantUpdate,
        alertType: alert.type,
        threshold: alert.threshold
      });
    }
  }
}

console.log(`Triggered ${alerts.length} price alerts`);

return alerts.map(alert => ({ json: alert }));

